#include <vector>
#include <cmath>
#include <algorithm>

class Solution {
public:
    int maxValueAfterReverse(std::vector<int>& nums) {
        int n = nums.size();
        if (n <= 1) return 0;

        int base = 0;
        for (int i = 0; i < n - 1; ++i) base += std::abs(nums[i] - nums[i + 1]);

        int max_gain = 0;
        for (int r = 1; r < n - 1; ++r) {
            int gain = std::abs(nums[0] - nums[r + 1]) - std::abs(nums[r] - nums[r + 1]);
            max_gain = std::max(max_gain, gain);
        }
        for (int l = 1; l < n - 1; ++l) {
            int gain = std::abs(nums[n - 1] - nums[l - 1]) - std::abs(nums[l] - nums[l - 1]);
            max_gain = std::max(max_gain, gain);
        }

        int min_hi = 1e9, max_lo = -1e9;
        for (int i = 0; i < n - 1; ++i) {
            int a = nums[i], b = nums[i + 1];
            min_hi = std::min(min_hi, std::max(a, b));
            max_lo = std::max(max_lo, std::min(a, b));
        }

        max_gain = std::max(max_gain, 2 * (max_lo - min_hi));
        return base + max_gain;
    }
};

